def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type') or text(val(ctx, 'task.task_type', '')))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place the wrong object at the destination; recover by setting it aside only if needed, then find the requested target.'
    elif stage == 'take_target':
        msg = 'A requested target type is available here. Take the target instead of continuing to search or handling a different object.'
    elif stage == 'transform':
        place = 'sinkbasin'
        if verb == 'heat':
            place = 'microwave'
        if verb == 'cool':
            place = 'fridge'
        if verb == 'slice':
            place = 'knife'
        msg = 'You are carrying the target. Before placing it, use the admissible ' + verb + ' action with the ' + place + ' or tool, then carry it to the requested destination.'
    elif stage == 'go_destination':
        msg = 'You are carrying the target. Go to the requested destination type and use the admissible put action there; do not put it on unrelated surfaces.'
    elif stage == 'put_target':
        msg = 'The requested destination put action is available. Put the carried target in/on the requested destination now.'
    elif stage == 'find_target' and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers and surfaces for the requested target type. Do not substitute a similar object.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

